class SQL {
private:
    struct Table {
        int nextId = 1;
        std::unordered_map<int, std::vector<std::string>> rows;
    };
    std::unordered_map<std::string, Table> tables;

public:
    SQL(std::vector<std::string>& names, std::vector<int>& columns) {
        for (const auto& name : names) {
            tables[name] = Table();
        }
    }

    void insertRow(std::string name, std::vector<std::string> row) {
        auto& tbl = tables[name];
        tbl.rows[tbl.nextId++] = std::move(row);
    }

    void deleteRow(std::string name, int rowId) {
        tables[name].rows.erase(rowId);
    }

    std::string selectCell(std::string name, int rowId, int columnId) {
        return tables[name].rows[rowId][columnId - 1];
    }
};

class SQL {
    static class Table {
        int nextId = 1;
        java.util.Map<Integer, java.util.List<String>> rows = new java.util.HashMap<>();
    }

    private java.util.Map<String, Table> tables = new java.util.HashMap<>();

    public SQL(java.util.List<String> names, java.util.List<Integer> columns) {
        for (String name : names) {
            tables.put(name, new Table());
        }
    }

    public void insertRow(String name, java.util.List<String> row) {
        Table tbl = tables.get(name);
        tbl.rows.put(tbl.nextId++, row);
    }

    public void deleteRow(String name, int rowId) {
        tables.get(name).rows.remove(rowId);
    }

    public String selectCell(String name, int rowId, int columnId) {
        return tables.get(name).rows.get(rowId).get(columnId - 1);
    }
}

var SQL = function(names, columns) {
    this.tables = new Map();
    for (const name of names) {
        this.tables.set(name, { nextId: 1, rows: new Map() });
    }
};

SQL.prototype.insertRow = function(name, row) {
    const tbl = this.tables.get(name);
    tbl.rows.set(tbl.nextId++, row);
};

SQL.prototype.deleteRow = function(name, rowId) {
    this.tables.get(name).rows.delete(rowId);
};

SQL.prototype.selectCell = function(name, rowId, columnId) {
    return this.tables.get(name).rows.get(rowId)[columnId - 1];
};
